import {Pressable, View} from 'react-native';
import HeaderCM from '../../../../../../../../components/Header/HeaderCM';
import TextCM from '../../../../../../../../components/Text';
import {Divider, Icon, List, ListItem} from '@ui-kitten/components';
import {useState} from 'react';
import TextFieldCM from '../../../../../../../../components/TextField';
import {Color} from '../../../../../../../../../constants';

type Props = {
  onClose: () => void;
  onSave: (data: string[]) => void;
};

const AddUrl = ({onClose, onSave}: Props) => {
  const [listUrl, setListUrl] = useState<string[]>([]);
  const [valueUrl, setValueUrl] = useState<string>('');

  const handleAdd = () => {
    setListUrl([...listUrl, valueUrl]);
    setValueUrl('');
  };
  const handleDelete = (index: number) => {
    setListUrl(prev => prev?.filter((_, i) => i !== index));
  };
  return (
    <>
      <HeaderCM
        style={{
          backgroundColor: '#fff',
        }}
        titleStyle={{
          color: '#00204D',
        }}
        fillIconBackLeft="#00204DB2"
        contentStyle={{
          backgroundColor: '#fff',
        }}
        title={'Thêm URL'}
        onPressIconLeft={onClose}
        renderContentRight={() => (
          <Pressable onPress={() => onSave(listUrl)}>
            <TextCM>Hoàn tất</TextCM>
          </Pressable>
        )}
      />
      <Divider />

      <View style={{flex: 1, padding: 16, rowGap: 16}}>
        <View
          style={{
            flexDirection: 'row',
            columnGap: 8,
            alignItems: 'center',
          }}>
          <TextFieldCM
            style={{flex: 1}}
            containerStyle={{flex: 1}}
            value={valueUrl}
            label="Nhập URL"
            onChangeText={setValueUrl}
          />
          <Pressable
            onPress={handleAdd}
            style={{
              height: 48,
              alignItems: 'center',
              justifyContent: 'center',
              backgroundColor: Color.BgPrimary,
              borderRadius: 8,
              paddingHorizontal: 10,
            }}>
            <TextCM style={{color: Color.White}}>Thêm</TextCM>
          </Pressable>
        </View>

        <List
          style={{backgroundColor: '#fff'}}
          data={listUrl}
          renderItem={({item, index}) => (
            <ListItem
              onPress={() => handleDelete(index)}
              title={item}
              accessoryRight={<Icon name="close" />}
            />
          )}
        />
      </View>
    </>
  );
};

export default AddUrl;
