import { View} from 'react-native';
import HeaderCM from '../../../components/Header/HeaderCM';
import {useTranslation} from 'react-i18next';
import {
  Icon,
  IconElement,
  IndexPath,
  Menu,
  MenuGroup,
  MenuItem,
} from '@ui-kitten/components';
import {useEffect, useState} from 'react';
import {useHomeService} from '../../../../hooks/useHomeService';
import {useNavigation} from '@react-navigation/native';
import {NavigationName} from '../../../../constants';

const PeopleIcon = (props: any): IconElement => (
  <Icon {...props} name="people-outline" />
);
const EyeIcon = (props: any): IconElement => (
  <Icon {...props} name="eye-outline" />
);
const ListIcon = (props: any): IconElement => (
  <Icon {...props} name="list-outline" />
);

const WorkSpace = ({route}: any) => {
  const {t} = useTranslation();
  const navigation = useNavigation<any>();
  const {spaceId, spaceName} = route?.params;
  const [selectedIndex, setSelectedIndex] = useState<IndexPath | undefined>(
    undefined,
  );
  const [tasks, setTasks] = useState<any[]>([]);

  const handleDetail = (task: any) => {
    navigation.navigate(NavigationName.TaskScreen, {
      taskId: task.id,
      taskSpaceId: spaceId,
      taskName: task.name,
    });
  };

  const HomeService = useHomeService();

  const ListTask = async () => {
    try {
      const res = await HomeService.getListWorkPlace(spaceId);
      setTasks(res.data || []);
    } catch (error) {
      console.log(error);
    }
  };

  useEffect(() => {
    ListTask();
  }, []);

  return (
    <View>
      <HeaderCM title={spaceName} showIconBackLeft={true} />
      <View>
        <Menu
          scrollEnabled={false}
          selectedIndex={selectedIndex}
          onSelect={index => setSelectedIndex(index)}>
          <MenuGroup title={'Thành viên'} accessoryLeft={PeopleIcon} />
          <MenuGroup title={'Dạng xem'} accessoryLeft={EyeIcon} />
          <MenuGroup title={'Danh sách công việc'} accessoryLeft={ListIcon}>
            {tasks.map((task, index) => (
              <MenuItem
                key={task.id}
                title={task.name}
                onPress={() => handleDetail(task)}
              />
            ))}
          </MenuGroup>
        </Menu>
      </View>
    </View>
  );
};

export default WorkSpace;
